// Design tokens for TypeScript. The values live in tokens.css (the one source); this file
// gives them typed names. Use `v("color-text")` in inline styles so a page still follows
// the stylesheet, and `tokenValue("color-text")` only where a plain value is needed
// (canvas, Lightweight Charts). tokens.gen.ts holds every token resolved, generated by
// `npm run tokens`, for code that runs without a page (share images, the Verify badge).
import { RAW, type TokenName } from "./tokens.gen";

export { RAW, type TokenName };

/** `var(--name)`, typed, for inline styles and SVG attributes. */
export const v = (name: TokenName): string => `var(--${name})`;

/** A token's live value on the page (follows app themes such as the Terminal's), or the
 *  value from tokens.css when there is no page or the property is unset. */
export function tokenValue(name: TokenName, el?: Element | null): string {
  if (typeof document !== "undefined") {
    const live = getComputedStyle(el ?? document.documentElement).getPropertyValue(`--${name}`).trim();
    if (live) return live;
  }
  return RAW[name];
}

/** A duration token in milliseconds, for scripted animation. 0 when reduced motion is on. */
export function durationMs(name: Extract<TokenName, `dur-${string}`>): number {
  if (typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return 0;
  const s = RAW[name];
  return s.endsWith("ms") ? parseFloat(s) : parseFloat(s) * 1000;
}

/** A type size token in px, for canvas text and chart libraries. */
export const typePx = (name: Extract<TokenName, `type-${string}`>): number => parseFloat(RAW[name]);

/** Breakpoints in px, the same numbers the stylesheets' media queries use. */
export const breakpoints = {
  phone: parseFloat(RAW["bp-phone"]),
  tablet: parseFloat(RAW["bp-tablet"]),
  laptop: parseFloat(RAW["bp-laptop"]),
  desktop: parseFloat(RAW["bp-desktop"]),
} as const;

/** Media queries built from the breakpoints, for matchMedia. */
export const media = {
  phone: `(max-width: ${breakpoints.phone - 1}px)`,
  tabletDown: `(max-width: ${breakpoints.tablet}px)`,
  laptopDown: `(max-width: ${breakpoints.laptop}px)`,
  wide: `(min-width: ${breakpoints.desktop}px)`,
  reducedMotion: "(prefers-reduced-motion: reduce)",
} as const;

/** Named colour roles, as CSS variables. */
export const color = {
  canvas: v("color-canvas"), bar: v("color-bar"), surface: v("color-surface"), surfaceRaised: v("color-surface-raised"),
  surfaceOverlay: v("color-surface-overlay"), glass: v("color-glass"), border: v("color-border"), borderStrong: v("color-border-strong"),
  text: v("color-text"), textBody: v("color-text-body"), textMuted: v("color-text-muted"), textFaint: v("color-text-faint"),
  accent: v("color-accent"), accentText: v("color-accent-text"), accentSoft: v("color-accent-soft"),
  primary: v("color-primary"), onPrimary: v("color-on-primary"),
  positive: v("color-positive"), negative: v("color-negative"), warning: v("color-warning"), info: v("color-info"),
  focus: v("color-focus"), glow: v("color-glow"),
} as const;

/** The chart series colours in their fixed order (REF-0009 rule 4). */
export const SERIES = ["series-1", "series-2", "series-3", "series-4", "series-5", "series-6", "series-7", "series-8"] as const satisfies readonly TokenName[];

/** z-index layers, lowest first. */
export const z = {
  backdrop: v("z-backdrop"), below: v("z-below"), base: v("z-base"), raised: v("z-raised"), sticky: v("z-sticky"),
  header: v("z-header"), nav: v("z-nav"), navScrim: v("z-nav-scrim"), panel: v("z-panel"), overlay: v("z-overlay"),
  popover: v("z-popover"), tooltip: v("z-tooltip"), modal: v("z-modal"), toast: v("z-toast"),
  assistant: v("z-assistant"), fullscreen: v("z-fullscreen"), top: v("z-top"),
} as const;
